import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const u=JSON.parse('{"title":"30、【離】 離下離上","description":"周易口訣義 - 30、【離】 離下離上","frontmatter":{"title":"30、【離】 離下離上","description":"周易口訣義 - 30、【離】 離下離上"},"headers":[],"relativePath":"classics/koujueyi/032.md","filePath":"classics/koujueyi/032.md"}'),r={name:"classics/koujueyi/032.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_30、【離】-離下離上" tabindex="-1">30、【離】 離下離上 <a class="header-anchor" href="#_30、【離】-離下離上" aria-label="Permalink to “30、【離】 離下離上”">​</a></h1><p>彖曰：離，麗也。日月麗乎天，百穀草木麗乎土，重明以麗乎正，乃化成天下。柔麗乎中正，故亨，是以「畜牝牛吉」也。</p><p>象曰：明兩作，離。大人以繼明照於四方。</p><p>初九：履錯然，敬之，無咎。</p><p>象曰：「履錯」之「敬」，以闢咎也。</p><p>六二：黃離，元吉。</p><p>象曰：「黃離元吉」，得中道也。</p><p>九三：日昃之離，不鼓缶而歌，則大耋之嗟，兇。</p><p>象曰：「日昃之離」，何可久也。</p><p>九四：突如其來如，焚如，死如，棄如。</p><p>象曰：「突如其來如」，無所容也。</p><p>六五：出涕沱若，戚嗟若，吉。</p><p>象曰：六五之吉，離王公也。</p><p>上九：王用出徵，有嘉折首，獲匪其醜，無咎。</p><p>象曰：「王用出徵」，以正邦也。</p><p>解讀</p><p>「離利貞亨」者，「離」，麗也，柔著於中正，柔而處中，恐陷邪謟，邪謟則不獲亨通，故須利貞正後乃得通，故「利貞亨」。麗猶著也，如出著於物也。「畜牝牛吉」者，畜，養也，牛者外強內順，然離之為體，故不可養剛猛之物，則可畜養牝牛，牛者順從之物而又牝焉。象曰「明兩作，離」者，上下重明相照，故云「明兩作，離」也。故東宮有重明門，欲令太子續於明也。「大人以繼明照於四方」者，繼明猶「緝熙」之義。</p><p>「初九，履錯然，敬之，無咎」者，履而錯然，謂不安之貌也。初九處無位之地，心常不安，常慮危害，若能恭敬為本，以避於害，即得「無咎」，故曰「敬之，無咎」也。</p><p>「六二，黃離，元吉」者，「黃」，中色也；「離」，文明也；得黃中之色，而又處文明，故復大吉也。</p><p>「九三，日昃之離，不鼓缶而歌，則大耋之嗟，兇」者，處下卦之上，如日昃之離，喻人中年以上，可委政於人，求己之樂；鼓缶而歌，樂天知命而已。若不知天命，獨親執政事，至於耋老嗟怨，無益，所以「兇」也。</p><p>「九四，突如其來如，焚如，死如，棄如」者，三處下離已沒之際，四為上離始出之初，「突如」始出，忽然而來，故曰「突如其來如」；欲進炎而焚於君，故曰「焚如」；以臣害君，命必不全，故曰「死如」也；違於臣節，眾之所棄，故曰「棄如」也。</p><p>「六五：出涕沱若，戚嗟若，吉」者，陰居陽位，不勝所履，四為逆首，欲來害己，若其出涕沱，憂戚嗟，如此戒懼，為眾所助，乃得「吉」也。</p><p>「上九：王用出徵，有嘉折首，獲匪其醜，無咎」者，處離之極，離道已盛，則須除其非類以去民害。故王用出征伐，必有嘉美之功，折斷罪人之首，獲得非類者，始可免咎。以處窮極之地，當須去民之害，乃得「無咎」，故曰「獲匪其醜，無咎」也。醜，類也。周易口訣義卷三，</p>',23)])])}const m=e(r,[["render",i]]);export{u as __pageData,m as default};
